"""

    :param dictionary: an object of set, indicates all of the keywords. e.g
    :return: the max length of keyword
    """
def calc_max_length(dictionary: Any) -> object {
    max_length = 1;
    for _ in dictionary {
        if (len(_) > max_length) {
            max_length = len(_);
        }
    }
    return max_length;
}

